#include <WiFi.h>
#include <SPI.h>
#include <Adafruit_GFX.h>
#include <Adafruit_ST7789.h>
#include <DHT.h>

// --- Cấu hình chân phần cứng ---
#define DHTPIN 14
#define DHTTYPE DHT11
DHT dht(DHTPIN, DHTTYPE);

#define PIR_PIN 13

// Màn hình màu 1.3 inch ST7789 (SPI)
#define TFT_CS    -1  
#define TFT_DC    9
#define TFT_RST   10
Adafruit_ST7789 tft = Adafruit_ST7789(TFT_CS, TFT_DC, TFT_RST);

// Động cơ Servo Pan-Tilt
#define SERVO_X_PIN 41
#define SERVO_Y_PIN 42

// Cấu hình Wi-Fi AP cho Robot
const char* ssid = "ESP32-S3-Robot";
const char* password = "12345678";
WiFiServer server(80);

// Hàm điều khiển góc quay Servo
void setServoAngle(int pin, int angle) {
  int duty = map(angle, 0, 180, 1638, 8192);
  ledcWrite(pin, duty);
}

// Hàm vẽ biểu cảm khuôn mặt lên màn hình 1.3 inch
void drawFace(String emotion) {
  tft.fillScreen(0x0000); // Màu đen
  if (emotion == "normal") {
    tft.fillCircle(70, 90, 15, 0x07E0); // Mắt xanh
    tft.fillCircle(170, 90, 15, 0x07E0);
    tft.fillRect(90, 150, 60, 8, 0x07E0); // Miệng cười
  } else {
    tft.fillCircle(70, 90, 18, 0xF800); // Mắt đỏ (báo động)
    tft.fillCircle(170, 90, 18, 0xF800);
    tft.fillCircle(120, 155, 12, 0xF800); // Miệng ngạc nhiên
  }
  tft.setCursor(75, 205);
  tft.setTextColor(0xFFFF); // Trắng
  tft.setTextSize(2);
  tft.print(emotion);
}

void setup() {
  Serial.begin(115200);

  // Khởi động cảm biến
  dht.begin();
  pinMode(PIR_PIN, INPUT);

  // Khởi động SPI cho màn hình ST7789 (Đặt MISO = -1 để giải phóng chân 13 cho PIR)
  SPI.begin(12, -1, 11, -1);
  tft.init(240, 240, SPI_MODE2);
  tft.setRotation(2);
  drawFace("normal");

  // Khởi động Servo PWM
  ledcAttach(SERVO_X_PIN, 50, 16);
  ledcAttach(SERVO_Y_PIN, 50, 16);
  setServoAngle(SERVO_X_PIN, 90);
  setServoAngle(SERVO_Y_PIN, 90);

  // Khởi động Wi-Fi Access Point
  WiFi.softAP(ssid, password);
  server.begin();
}

void loop() {
  // Đọc cảm biến nhiệt độ, độ ẩm và chuyển động
  float h = dht.readHumidity();
  float t = dht.readTemperature();
  int motion = digitalRead(PIR_PIN);

  // Xử lý logic khi phát hiện chuyển động
  if (motion == HIGH) {
    drawFace("motion"); // Đổi mặt trên màn hình ST7789
    setServoAngle(SERVO_X_PIN, 45);
    delay(250);
    setServoAngle(SERVO_X_PIN, 135);
    delay(250);
    setServoAngle(SERVO_X_PIN, 90);
  } else {
    drawFace("normal");
  }

  // Xử lý kết nối từ Web Client giám sát
  WiFiClient client = server.available();
  if (client) {
    String request = client.readStringUntil('\n');
    client.println("HTTP/1.1 200 OK");
    client.println("Content-Type: text/html; charset=utf-8");
    client.println("");
    client.println("<!DOCTYPE HTML><html><body>");
    client.println("<h2>ESP32-S3 AI Robot Control Panel</h2>");
    client.println("<p>Nhiệt độ môi trường: " + String(t) + " &deg;C</p>");
    client.println("<p>Độ ẩm không khí: " + String(h) + " %</p>");
    client.println("<p>Trạng thái PIR: " + String(motion ? "Phát hiện chuyển động!" : "An toàn") + "</p>");
    client.println("</body></html>");
    client.stop();
  }

  delay(1000);
}
